import api from "./api";

export const statusLabels = {
    REQUESTED: "Pending",
    ACCEPTED: "Accepted",
    STARTED: "In progress",
    COMPLETED: "Completed",
    CANCELLED: "Cancelled"
};

export function normalizeRide(ride) {
    const employee = ride.employee || ride.user || {};
    const driver = ride.cab?.driver || {};
    return {
        ...ride,
        employeeName: employee.name || "",
        employeeId: employee.employeeId || "",
        employeeEmail: employee.email || "",
        driverName: driver.name || "",
        driverId: driver.driverId || "",
        vehicleModel: ride.cab?.model || "",
        vehicleRegistration: ride.cab?.carNumber || "",
        billing: ride.billing || null
    };
}

export async function fetchRides() {
    const response = await api.get("/api/admin/all-rides");
    return (Array.isArray(response.data) ? response.data : []).map(normalizeRide);
}

export async function fetchAccounts() {
    const [employeesResponse, usersResponse, adminsResponse] = await Promise.all([
        api.get("/api/admin/all-employees"),
        api.get("/api/admin/all-users"),
        api.get("/api/admin/all-admins")
    ]);

    const users = Array.isArray(usersResponse.data) ? usersResponse.data : [];
    const employees = Array.isArray(employeesResponse.data) ? employeesResponse.data : [];
    const admins = Array.isArray(adminsResponse.data) ? adminsResponse.data : [];
    const uniqueByEmail = (items) => {
        const seen = new Set();
        return items.filter((item) => {
            const key = String(item.email || item.id || "");
            if (!key || seen.has(key)) return false;
            seen.add(key);
            return true;
        });
    };

    return {
        employees: uniqueByEmail([
            ...employees.map((employee) => ({ ...employee, accountType: "employee" })),
            ...users.filter((user) => user.role === "USER").map((user) => ({ ...user, accountType: "employee" }))
        ]),
        drivers: uniqueByEmail(users.filter((user) => user.role === "DRIVER")),
        admins: uniqueByEmail([
            ...admins,
            ...users.filter((user) => user.role === "ADMIN")
        ])
    };
}

export function formatCurrency(value) {
    if (value == null || !Number.isFinite(Number(value))) return "—";
    return new Intl.NumberFormat("en-IN", {
        style: "currency",
        currency: "INR",
        maximumFractionDigits: 2
    }).format(Number(value));
}

export function formatDate(value) {
    if (!value) return "—";
    const date = new Date(value);
    return Number.isNaN(date.getTime())
        ? "—"
        : date.toLocaleString("en-IN", {
            day: "2-digit",
            month: "short",
            year: "numeric",
            hour: "2-digit",
            minute: "2-digit"
        });
}

export function downloadCsv(filename, columns, rows) {
    const csv = [columns, ...rows]
        .map((row) => row.map((value) => `"${String(value ?? "").replaceAll('"', '""')}"`).join(","))
        .join("\r\n");
    const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
    const link = document.createElement("a");
    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);
}
